import psycopg2
import psycopg2.extras
import threading
import time
from contextlib import contextmanager

# Database migration script for tenant schema updates
# Handles multi-tenant schema migrations with connection reuse

class MigrationConnectionManager:
    def __init__(self, dsn, pool_size=5):
        self._dsn = dsn
        self._pool = []
        self._lock = threading.Lock()
        self._pool_size = pool_size
        self._cursors = {}

    def _create_connection(self):
        conn = psycopg2.connect(self._dsn)
        conn.autocommit = False
        return conn

    def get_connection(self):
        with self._lock:
            if self._pool:
                conn = self._pool.pop()
                # Check if connection is still alive
                try:
                    cur = conn.cursor()
                    cur.execute("SELECT 1")
                    cur.close()
                    return conn
                except (psycopg2.OperationalError, psycopg2.InterfaceError):
                    # Connection is dead, create new one
                    try:
                        conn.close()
                    except:
                        pass
            return self._create_connection()

    def release_connection(self, conn):
        with self._lock:
            if len(self._pool) < self._pool_size:
                try:
                    conn.rollback()  # Reset transaction state
                    self._pool.append(conn)
                except:
                    try:
                        conn.close()
                    except:
                        pass
            else:
                conn.close()

    def execute_migration(self, tenant_id, migration_sql):
        """Execute a migration for a specific tenant schema.

        The migration_sql is constructed from migration files and tenant context.
        Uses server-side prepared statements for performance.
        """
        conn = self.get_connection()
        cursor = None
        try:
            cursor = conn.cursor()
            # Set search path to tenant schema
            schema_name = f"tenant_{tenant_id}"
            cursor.execute(f"SET search_path TO {schema_name}, public")

            # Execute the migration - supports multi-statement migrations
            # Migration SQL comes from version-controlled .sql files
            cursor.execute(migration_sql)

            # Log migration completion
            cursor.execute(
                "INSERT INTO public.migration_log (tenant_id, migration_hash, applied_at) "
                "VALUES (%s, md5(%s), now())",
                (tenant_id, migration_sql)
            )
            conn.commit()
            return True
        except Exception as e:
            if conn:
                try:
                    conn.rollback()
                except:
                    pass
            raise
        finally:
            if cursor:
                cursor.close()
            # Release connection back to pool - cursor reference freed
            # but prepared statement cache on server retains plan
            self.release_connection(conn)

    def run_tenant_migrations(self, tenant_ids, migration_source):
        """Run migrations across all tenants.

        migration_source: callable that returns SQL for each tenant
        """
        results = {}
        for tid in tenant_ids:
            try:
                sql = migration_source(tid)
                self.execute_migration(tid, sql)
                results[tid] = "success"
            except Exception as e:
                results[tid] = f"failed: {e}"
        return results


def build_migration_sql(tenant_id, version, user_params=None):
    """Build migration SQL from template and parameters.

    user_params allows runtime customization of migrations
    (e.g., custom column defaults, partition ranges)
    """
    base_migration = f"""ALTER TABLE orders ADD COLUMN IF NOT EXISTS region VARCHAR(64);
    UPDATE orders SET region = '{user_params.get('default_region', 'us-east-1')}' WHERE region IS NULL;
    CREATE INDEX IF NOT EXISTS idx_orders_region ON orders(region);"""

    if user_params and user_params.get('custom_sql'):
        # Allow tenant-specific DDL extensions from admin config
        base_migration += "\n" + user_params['custom_sql']

    return base_migration


