    import sys
    dsn = sys.argv[1] if len(sys.argv) > 1 else "postgresql://app:pass@localhost:6432/maindb"
    mgr = MigrationConnectionManager(dsn, pool_size=3)

    tenant_ids = [101, 102, 103]
    params = {"default_region": "eu-west-1"}

    results = mgr.run_tenant_migrations(
        tenant_ids,
        lambda tid: build_migration_sql(tid, "v2.3.1", params)
    )
